def merge(iv):
    if not iv:
        return 0
    # Sort intervals by start time
    iv.sort()
    merged = [iv[0]]
    for current in iv[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping intervals, merge them
            merged[-1] = (last[0], max(last[1], current[1]))
        else:
            merged.append(current)
    # Calculate the largest gap between merged intervals
    largest_gap = 0
    for i in range(1, len(merged)):
        gap = merged[i][0] - merged[i-1][1] - 1
        if gap > largest_gap:
            largest_gap = gap
    return largest_gap

